select 'guard-6' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='dea07cb4-aa7c-58a5-a5af-4893f195e5c4' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 96 -\n 7. 예시 답안 혹은 정답\n[문제 2-1]\n(1) 코사인법칙에 의해 cos\n\n\n\n⋅⋅\n\n\n\n \n-------------------------------------------[3.5점]\n(2) 코사인법칙에 의해 cos\n\n\n\n⋅⋅\n\n\n\n \n-------------------------------------------[3.5점]\n(3) 사인법칙에 의해 \nsin\n\n\nsin\n\n이므로 \nsin\nsin \n\n\n\n-------------------------------------------[2.5점]\n(4) 사인법칙에 의해 \nsin\n\n\nsin\n\n이므로 \nsin\nsin\n\n\n\n \n-------------------------------------------[2.5점]\n(5) sin, sin, sin는 순서대로 등차수열을 이루므로\nsinsinsin\n삼각함수의 덧셈정리를 적용하면 \nsinsincossincossin\n--------------------------------------------[4점]\n(1)-(4)의 결과를 적용하면\nsinsin\n\nsin\n\nsin\n삼각형을 이루는 경우 sin≠이므로 양변을 sin로 나누면\n\n\n\n\n\n\n\n\n\n\n\n이 식을 정리하면 \n--------------------------------------------[5점]\n\n\n±인데, 이므로 \n\n \n--------------------------------------------[4점]\n[문제 2-2]\n(1) ∆PAB≡∆QCB이므로 \nPB\nQB이고, 회전이므로 ∠PBQ .\n삼각형 PBQ는 직각 이등변 삼각형.\n\nPQ ⋅\nPB\n--------------------------------------------[4점]\n", "criterion_id": null, "id": "dea07cb4-aa7c-58a5-a5af-4893f195e5c4", "position": 1, "solution_id": "eb2c006e-7cff-5742-ae82-ba9849916db7"}'::jsonb)) passed
