select 'guard-19' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='ba0fabf8-7a14-5ec8-84b4-2740c672acc4' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 6 -\n 7. 예시 답안 혹은 정답\n[답안 1-1] \n집합의 조건에 따르면 이고 집합의 조건에 따라 임. ± \n. \n따라서 ∩임.\n채점기준\n----------------------------------------------\n정답: 인 경우                                                        10점 \n----------------------------------------------\n정답: 인 경우                                                          8.2점\n----------------------------------------------\n정답:  또는  등 1개만 맞는 경우                           4.2점\n----------------------------------------------\n정답:  또는  등 1개만 맞고, 집합 기호를 안 쓴 경우           3.2점\n[답안 1-2] \n(1) \n    lim\n→０\n\n\n    lim\n→\n\n\n   즉, lim\n→０\n\n의 값이 존재하지 않으므로 함수 는 에서 미분가능하지 \n않다.\n--- ------ ------ ------ ------ ------ ------ 총 6 점\n(2) 미분가능하지 않은 의 값은 , , , ,  \n근거 예시 1) 그래프를 그리고 찾기\n근거 예시 2) 각 점에서 미분계수를 계산한 경우\n채점 기준표\n  답을 맞추고 근거를 제시한 경우 ------------------------6점\n  답만 모두 맞춘 경우 -------------------------------5.1점\n  답에서 하나 이상 빠진 경우 ---------------------------3.2점\n", "criterion_id": null, "id": "ba0fabf8-7a14-5ec8-84b4-2740c672acc4", "position": 1, "solution_id": "3ee9990f-cb03-53a6-90c4-efd90626ef84"}'::jsonb)) passed
