select 'guard-20' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='ac240101-a7dd-53f0-a3e5-546064a275c5' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 7 -\n  답에서 틀린 점을 포함하는 경우 ----------------------- 3.2점 \n  답에서 정답이 하나도 없는 경우 - - - - - - - - - - - - - - - - - - - 0 점\n-------------------------------------------총 6점\n[답안 1-3] \n  (1) \nR, R\n\n, R\n\n\n, O\n\n\n, O\n\n\n\n      각 좌표당 1점 \n------------------------------------------ 총 5점\n (2) \n   점O의 좌표는 \nO\n\n\n\n\n   으로 계산할 수 있음.  \n--------------------------------------------- 3점\nO\n\n\n\n\n--------------------------------------------- 3점\n총 6점\n(3)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n, \n------------------------------------------    8점\n(4) \n직선 OO의 기울기는 \n", "criterion_id": null, "id": "ac240101-a7dd-53f0-a3e5-546064a275c5", "position": 2, "solution_id": "3ee9990f-cb03-53a6-90c4-efd90626ef84"}'::jsonb)) passed
