select 'guard-21' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='5dece099-8bcf-57e9-86a6-9530078a75ed' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 8 -\n\n\n\n\n\n\n\n\n\n\n\n\n--------------------------------------------- 3점\n가장 먼 거리에 있는 점은 기울기가 \n\n인 접선과 만나는 접점이므로 \n\n\n\n,\n\n\n\n 이므로 \n\n (또는 \n\n\n\n)\n--------------------------------------------  6점\n총 9점\n", "criterion_id": null, "id": "5dece099-8bcf-57e9-86a6-9530078a75ed", "position": 3, "solution_id": "3ee9990f-cb03-53a6-90c4-efd90626ef84"}'::jsonb)) passed
