select 'guard-34' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='8bf180dd-1624-5e12-ae88-b3e7692345f2' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 86 -\nlim\n→\nlim\n→\n\n\n따라서\n 이다. \n-----------------------------------------------------------------------------------------[2점]\n(2) ′의 값 (5점)\n(1)에 의해 일 때 \n\n이다.\n-----------------------------------------------------------------------------------------[1점]\n의 분자를 , 분모를 라 하자. \n, 이다. \n함수 의 도함수 ′ 는\n′\n\n′′\n\n\n\n\n-----------------------------------------------------------------------------------------[2점]\n따라서, \n′\n\n\n\n\n\n-----------------------------------------------------------------------------------------[2점]\n[다른 풀이]\n(2) ′의 값 (5점)\n(1)에 의해 일 때 \n\n이다.\n의 분자를 , 분모를 라 하자. \n, 이다. \n-----------------------------------------------------------------------------------------[1점]\n≠일 때 함수 의 도함수 ′ 는\n′\n\n′′\n\n\n\n\n-----------------------------------------------------------------------------------------[2점]\n미분계수의 정의를 이용하면 다음과 같다. \n′lim\n→\n\n\n", "criterion_id": null, "id": "8bf180dd-1624-5e12-ae88-b3e7692345f2", "position": 2, "solution_id": "454d0cf7-3794-5e96-92f2-f8c9fcfefbdd"}'::jsonb)) passed
