select 'guard-35' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='628f29e9-ccc9-5768-bcfd-86b42479b22c' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 87 -\n′lim\n→\n\nlim\n→\n\nlim\n→\n\n\n\n\nlim\n→\n\n\n\n따라서, ′\n\n-----------------------------------------------------------------------------------------[2점]\n(3) 함수 가 증가하는 구간 (5점)\n도함수 ′ 에서 ′\n\n 이므로\n′ 에서   ()\n-----------------------------------------------------------------------------------------[2점]\n함수 의 증가와 감소를 나타내는 표를 만들면 \n\n\n⋯\n\n⋯\n′\n\n\n\n\n\n↘\n\n↗\n따라서, 함수 는 구간 ∞에서 증가한다. \n-----------------------------------------------------------------------------------------[3점]\n[정답 1-2] (총 15점)\ncos cos cos cos \ncos sin sin cos sin \n(1) \n\n를 에 대한 식 (5점)\n식 , 를 로 미분을 하면\n\n\nsin sin cos cos sin sin sin \n\n\ncos sin sin cos cos cos cos \n-----------------------------------------------------------------------------------------[3점]\n따라서, \n\n를 에 대한 식으로 표현하면 다음과 같다.\n", "criterion_id": null, "id": "628f29e9-ccc9-5768-bcfd-86b42479b22c", "position": 3, "solution_id": "454d0cf7-3794-5e96-92f2-f8c9fcfefbdd"}'::jsonb)) passed
