select 'guard-36' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='f0e6d1f1-a063-5f91-9904-5896ea7122b5' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 88 -\n\n\n\n\n\n\n\n\n\n\nsin sin \ncos cos \nsin sin \ncos cos \nsin sin \ncos cos \n-----------------------------------------------------------------------------------------[2점]\n(2) 점 P의 속력 이 최대가 되는 시각  및 점 P의 위치 (6점)\n점 P의 속력 는 다음과 같다. \n\n\n\n\n\n\n\n\n\n\nsinsin sin sincoscos cos cos\n\nsin sin cos cos \n\nsincos cos sin\n\ncos \n\ncos\n\ncos\ncos \n≤≤\n\n---------------------------------➀\n-----------------------------------------------------------------------------------------[3점]\n식 ➀에서 속력 이 최대인 시각은  이므로\n-----------------------------------------------------------------------------------------[2점]\nP의 위치는 이다. \n-----------------------------------------------------------------------------------------[1점]\n(3) 점 P가 움직인 거리 (4점)\n점 P가 움직인 거리를 라 하자.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\ncos \n\n≤≤\n\n이므로 cos cos \n-----------------------------------------------------------------------------------------[2점]\n\n\n\n\n\n\ncos \n", "criterion_id": null, "id": "f0e6d1f1-a063-5f91-9904-5896ea7122b5", "position": 4, "solution_id": "454d0cf7-3794-5e96-92f2-f8c9fcfefbdd"}'::jsonb)) passed
