select 'guard-37' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='1d3b5555-f908-5b5d-a849-83dd7860fe30' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 89 -\nsin \n\n\n\n\n\n\n따라서, 거리는 8이다. \n-----------------------------------------------------------------------------------------[2점]\n[정답 1-3] (총 20점)\n(1) 의 값 (4점)\ncos  로 치환하면, \n\nsin  이고,\n 일 때 ,\n\n일 때  이므로\n-----------------------------------------------------------------------------------------[1점]\n\n\n\n\ncos \nsin \n\n\n\n\n\n\n\n\n\n\n\nln \n\n\nln \n따라서 \n\nln \n-----------------------------------------------------------------------------------------[3점]\n(2) 함수 가 연속인지 불연속인지 조사 (8점)\n 일 때,\n\n\n\n\nsin cos \n\n\n\n-----------------------------------------------------------------------------------------[1점]\n 일 때,\ncos  로 치환하면, \n\nsin  이고,\n 일 때 ,\n\n 일 때  이므로\n", "criterion_id": null, "id": "1d3b5555-f908-5b5d-a849-83dd7860fe30", "position": 5, "solution_id": "454d0cf7-3794-5e96-92f2-f8c9fcfefbdd"}'::jsonb)) passed
