select 'guard-38' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='52e65112-9452-5b8a-bbb7-f274c75ae338' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 90 -\n\n\n\n\ncos \nsin \n\n\n\n\n\n\n\n\n\n\n\n\nln \n\n\nln \n\n\nln \n-----------------------------------------------------------------------------------------[3점]\n따라서, \n\n\n\n\n\n\n\n\n\nln \n이고, 이면 ln 과 \n는 연속이므로 는 연속이다.\n-----------------------------------------------------------------------------------------[2점]\n일 때,\nlim\n→lim\n→\n\nln \nlim\n→\n따라서, 는 ≥에서 연속이다.\n-----------------------------------------------------------------------------------------[2점]\n(3) 함수 의 증가와 감소를 조사 (8점)\n\n\nln 의 증감 확인 \n에서 ′일 때 증가, ′ 일 때 감소한다. \n\n\nln \n′\n\nln \n\n\n\n\n\nln\n-----------------------------------------------------------------------------------------[3점]\n′의 분자를 , 분모를 라 하자. \n분모 이므로 ′의 부호와 의 부호는 같다.\nln\n\n′lnln이므로\n 일 때 ′\n즉, 에서  이다.\n", "criterion_id": null, "id": "52e65112-9452-5b8a-bbb7-f274c75ae338", "position": 6, "solution_id": "454d0cf7-3794-5e96-92f2-f8c9fcfefbdd"}'::jsonb)) passed
