select 'guard-39' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='1459e0e8-5442-556a-ad67-7ffff0aa6262' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 91 -\n-----------------------------------------------------------------------------------------[3점]\n 일 때 ′ 이므로 는 감소한다.\n≥일 때 는 연속이고,  일 때 는 미분가능하므로\n따라서, ≥ 일 때 는 감소한다.\n-----------------------------------------------------------------------------------------[2점]\n[다른 풀이]\n(3) 함수 의 증가와 감소를 조사 (8점)\n임의의 실수 , 가 구간 ∞내에 있고 구간 ≤≤\n에서 cos ≥, sin ≥ 가 성립된다. \n일 때 \ncos cos \n-----------------------------------------------------------------------------------------[2점]\n\ncos \nsin \n\ncos \nsin \n-----------------------------------------------------------------------------------------[2점]\n따라서,\n\n\n\n\ncos \nsin \n\n\n\n\ncos \nsin \n 가 성립하여 는 감소한다.\n-----------------------------------------------------------------------------------------[4점]\n", "criterion_id": null, "id": "1459e0e8-5442-556a-ad67-7ffff0aa6262", "position": 7, "solution_id": "454d0cf7-3794-5e96-92f2-f8c9fcfefbdd"}'::jsonb)) passed
