select 'guard-59' check_name,(exists(select 1 from public.math_scoring_criteria where id='6a30279c-3084-5143-96e5-bc969ff862bc' and to_jsonb(math_scoring_criteria) @> '{"criterion_key": "q2-official-page-13", "description": "- 13 -\n하위문항\n채점기준\n배점\n2-1\n, , 을 구할 수 있다.\n3\n\n을 구할 수 있다.\n3\n\n을 구할 수 있다.\n3\n\n을 구할 수 있다.\n3\n\n을 구할 수 있다.\n5\n\n\n을 구할 수 있다.\n4\n2-2\n∠PYX ∠YXB 임을 보일 수 있다.\n3\n\n\nPY\n\nPA \nsin∠PAY\nsin∠PYA 임을 구할 수 있다.\n1.5\n\n\nBX\n\nAB \nsin∠BAX\nsin∠AXB 임을 구할 수 있다.\n1.5\nsin∠PYA sin∠PYX\nsin∠PYX\nsin∠YXB\nsin∠AXB\n의 관계식을 구할 수 있다.\n3\n\nZP\nPY의 값을 구할 수 있다.\n4\n\nBC의 값을 구할 수 있다.\n3\n\nWQ\nYQ라 할 때, \nPQ, \nAQ의 관계식을 구할 수 있다.\n2\ncos∠BAC \n\nAB⋅\nAC\n\nAB\n\nAC\n\nBC\n\n\n⋅⋅\n\n\n\n의 구할 수 있다.\n3\ncos∠PAQ \n\nAP⋅\nAQ\n\nAP\n\nAQ\n\nPQ\n\n\n⋅⋅\n\n\n\n의 구할 수 \n있다.\n3\n\nWQ\n의 값을 구할 수 있다.\n5\n 7. 예시 답안 혹은 정답\n[답안 2-1] \n주어진 세 관계식으로부터 , , 을 얻을 수 있다.\n---------------------------------------(3점)\n가 최고차항의 계수가 인 삼차식이므로 \n또는 \n", "id": "6a30279c-3084-5143-96e5-bc969ff862bc", "leaf_id": "dde4effa-358f-5a69-871a-d09cb460bc50", "official_points": null, "rubric_dimensions": ["logical_development", "computation_accuracy", "final_conclusion"], "source_id": "f73b5a6f-251e-54c9-a027-d1e0f5699a9e"}'::jsonb)) passed
