select 'guard-66' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='719ba016-83ac-52f7-bf78-851eb6f5b591' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 14 -\n 7. 예시 답안 혹은 정답\n[문제 2-1]\n(1) (5점)\n ′이므로\n ± 일 때, ′.\n ± 에서 의 증가와 감소를 조사하면 다음과 같다.\n\n⋯\n\n⋯\n\n⋯\n′\n-\n\n+\n\n-\n\n↘\n극소\n↗\n극대\n↘\n 따라서 에서 극솟값 를 갖고 에서 극댓값 를 갖는다.\n------------------------------------------------------[4점]  \n 그러므로 와 를 지나는 직선의 기울기는 \n\n이다.\n-------------------------------------------------------[1점]  \n(2) (7점)\n직선 와 가 만나는 점은 가 만나는 점의 개수이므로, 와 의 교점의 \n개수를 구하자. 즉, \n 라 할 때, ′이므로, ±\n\n\n일 때 ′이다. \n 의 증가와 감소를 조사하면 다음과 같다.\n\n⋯\n\n\n\n\n⋯\n\n\n\n\n⋯\n′\n-\n\n+\n\n-\n\n↘\n\n\n\n↗\n\n\n\n↘\n------------------------------------------------------[5점]\n따라서 는 \n\n\n\n일 때 와 서로 다른 세 점에서 만난다.\n------------------------------------------------------[2점]\n[문제 2-2]\n(1) (5점)\n 이 서로 다른 두 실근을 가지려면 이어야 하므로 \n  \n 따라서 \n\n이다. ------① \n------------------------------------------------------------[3점]\n 그런데 두 근이 모두 양수이려면 두 근의 합과 곱이  보다 커야 하므로 과 ≠을 만족해야 한다.--②\n------------------------------------------------------------[1점]\n 따라서 ①과 ②에 의해 \n\n, 이다.\n------------------------------------------------------------[1점]\n", "criterion_id": null, "id": "719ba016-83ac-52f7-bf78-851eb6f5b591", "position": 1, "solution_id": "515d7ac5-7e28-5c47-bb6c-13838ce503d5"}'::jsonb)) passed
