select 'guard-67' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='a466161d-8a77-530c-aef1-9b0072907e33' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 15 -\n(2) (8점)\n \n\n의 순서로 등차수열을 이루고 있으므로, 등차수열의 성질에 의해 \n\n이므로\n \n, 즉 이다. \n 또한 근과 계수의 관계에 의해 \n---①이고 ---②이므로,\n------------------------------------------------------------[6점]\n ①에서 \n를 ②에 대입하면, \n.\n 에 대한 이차방정식을 풀면 의 값은 \n. \n------------------------------------------------------------[2점]\n[문제 2-3]\n(1) (6점) \n 함수 의 그래프와 직선 가 만나는 서로 다른 두 점의 좌표를 구하면 A, B이다.\n------------------------------------------------------------[2점]\n 코사인법칙에 의하여 cos∠AOB\n\nOA\nOB\n\nOA\n\nOB\n\nAB\n\n에서\n\nAB이므로, \nOA\n, \nOB\n, \nAB\n.\n따라서 cos∠AOB\n\n\n\n\n.\n------------------------------------------------------------[4점]\n(2) (4점) \n lim\n→∞\nlim\n→∞\n\n\n\n\nlim\n→∞\n\n\n\n\n\n\n\n\n\n\n.\n------------------------------------------------------------[4점]\n[문제 2-4] \n(15점)\n \n\n\n\n\n\n\n이므로 ---①을 만족한다.\n------------------------------------------------------------[3점]\n정적분 \n\n\n\n\n\n\n\n\n\n\n\n\n           =\n ---②\n------------------------------------------------------------[3점]\n②에 ①을 대입하여 정리하면 \n\n이므로,\n------------------------------------------------------------[3점]\n", "criterion_id": null, "id": "a466161d-8a77-530c-aef1-9b0072907e33", "position": 2, "solution_id": "515d7ac5-7e28-5c47-bb6c-13838ce503d5"}'::jsonb)) passed
