select 'guard-68' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='5b06648c-690d-5cc5-a80a-e89049794cd3' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 16 -\n를 미분하면 ′ \n\n\n이고, 의 증가와 감소를 구하면 다음과 같다.\n\n⋯\n\n\n⋯\n\n⋯\n′\n-\n\n+\n\n-\n\n↘\n\n\n\n↗\n\n↗\n따라서 는 \n에서 최솟값 \n\n를 갖는다.\n------------------------------------------------------------[6점]\n", "criterion_id": null, "id": "5b06648c-690d-5cc5-a80a-e89049794cd3", "position": 3, "solution_id": "515d7ac5-7e28-5c47-bb6c-13838ce503d5"}'::jsonb)) passed
