select 'guard-69' check_name,(exists(select 1 from public.math_canonical_solutions where id='515d7ac5-7e28-5c47-bb6c-13838ce503d5' and to_jsonb(math_canonical_solutions) @> '{"body": "- 14 -\n 7. 예시 답안 혹은 정답\n[문제 2-1]\n(1) (5점)\n ′이므로\n ± 일 때, ′.\n ± 에서 의 증가와 감소를 조사하면 다음과 같다.\n\n⋯\n\n⋯\n\n⋯\n′\n-\n\n+\n\n-\n\n↘\n극소\n↗\n극대\n↘\n 따라서 에서 극솟값 를 갖고 에서 극댓값 를 갖는다.\n------------------------------------------------------[4점]  \n 그러므로 와 를 지나는 직선의 기울기는 \n\n이다.\n-------------------------------------------------------[1점]  \n(2) (7점)\n직선 와 가 만나는 점은 가 만나는 점의 개수이므로, 와 의 교점의 \n개수를 구하자. 즉, \n 라 할 때, ′이므로, ±\n\n\n일 때 ′이다. \n 의 증가와 감소를 조사하면 다음과 같다.\n\n⋯\n\n\n\n\n⋯\n\n\n\n\n⋯\n′\n-\n\n+\n\n-\n\n↘\n\n\n\n↗\n\n\n\n↘\n------------------------------------------------------[5점]\n따라서 는 \n\n\n\n일 때 와 서로 다른 세 점에서 만난다.\n------------------------------------------------------[2점]\n[문제 2-2]\n(1) (5점)\n 이 서로 다른 두 실근을 가지려면 이어야 하므로 \n  \n 따라서 \n\n이다. ------① \n------------------------------------------------------------[3점]\n 그런데 두 근이 모두 양수이려면 두 근의 합과 곱이  보다 커야 하므로 과 ≠을 만족해야 한다.--②\n------------------------------------------------------------[1점]\n 따라서 ①과 ②에 의해 \n\n, 이다.\n------------------------------------------------------------[1점]\n\n\n- 15 -\n(2) (8점)\n \n\n의 순서로 등차수열을 이루고 있으므로, 등차수열의 성질에 의해 \n\n이므로\n \n, 즉 이다. \n 또한 근과 계수의 관계에 의해 \n---①이고 ---②이므로,\n------------------------------------------------------------[6점]\n ①에서 \n를 ②에 대입하면, \n.\n 에 대한 이차방정식을 풀면 의 값은 \n. \n------------------------------------------------------------[2점]\n[문제 2-3]\n(1) (6점) \n 함수 의 그래프와 직선 가 만나는 서로 다른 두 점의 좌표를 구하면 A, B이다.\n------------------------------------------------------------[2점]\n 코사인법칙에 의하여 cos∠AOB\n\nOA\nOB\n\nOA\n\nOB\n\nAB\n\n에서\n\nAB이므로, \nOA\n, \nOB\n, \nAB\n.\n따라서 cos∠AOB\n\n\n\n\n.\n------------------------------------------------------------[4점]\n(2) (4점) \n lim\n→∞\nlim\n→∞\n\n\n\n\nlim\n→∞\n\n\n\n\n\n\n\n\n\n\n.\n------------------------------------------------------------[4점]\n[문제 2-4] \n(15점)\n \n\n\n\n\n\n\n이므로 ---①을 만족한다.\n------------------------------------------------------------[3점]\n정적분 \n\n\n\n\n\n\n\n\n\n\n\n\n           =\n ---②\n------------------------------------------------------------[3점]\n②에 ①을 대입하여 정리하면 \n\n이므로,\n------------------------------------------------------------[3점]\n\n\n- 16 -\n를 미분하면 ′ \n\n\n이고, 의 증가와 감소를 구하면 다음과 같다.\n\n⋯\n\n\n⋯\n\n⋯\n′\n-\n\n+\n\n-\n\n↘\n\n\n\n↗\n\n↗\n따라서 는 \n에서 최솟값 \n\n를 갖는다.\n------------------------------------------------------------[6점]\n", "id": "515d7ac5-7e28-5c47-bb6c-13838ce503d5", "leaf_id": "2a5f8c6d-f076-517e-af42-3da22e7da820", "logical_id": "515d7ac5-7e28-5c47-bb6c-13838ce503d5", "origin": "OFFICIAL", "source_id": "c123e1b6-e74e-5c37-88a4-e632f1ae97d8", "state": "DRAFT", "version": 1}'::jsonb)) passed
union all
select 'guard-70' check_name,(exists(select 1 from public.math_evaluation_profiles where id='d4f16c33-2f4c-5bcb-b24a-57fb300f0f3b' and to_jsonb(math_evaluation_profiles) @> '{"id": "d4f16c33-2f4c-5bcb-b24a-57fb300f0f3b", "leaf_id": "2a5f8c6d-f076-517e-af42-3da22e7da820", "logical_id": "d4f16c33-2f4c-5bcb-b24a-57fb300f0f3b", "reasoning_required": true, "required_dimensions": ["logical_development", "computation_accuracy", "final_conclusion"], "response_format": "FULL_SOLUTION", "rubric_version": "math-rubric-v1", "scope": "LEAF", "state": "DRAFT", "version": 1}'::jsonb)) passed
