select 'guard-71' check_name,(exists(select 1 from public.math_problem_sets where id='58ff0e95-e3b6-5e19-8c5d-35b451c20af0' and to_jsonb(math_problem_sets) @> '{"essay_exam_id": "51d7f36d-a011-5279-8c5d-f731b2900af3", "id": "58ff0e95-e3b6-5e19-8c5d-35b451c20af0", "label": "한국항공대 2024 이학계열 문제 2", "logical_id": "58ff0e95-e3b6-5e19-8c5d-35b451c20af0", "state": "DRAFT", "version": 1}'::jsonb)) passed
