select 'guard-81' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='37451834-725d-5364-bbab-1e4868f570c8' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 14 -\n[풀이1]\n--① \n이므로 이다.\n≤이므로 이다.\n따라서 을 만족하는 자연수 이다.\n------------------------------------------------------[3점]  \n을 ①에 대입하면, \n ---②\n따라서 ②와 ≤을 동시에 만족하는 의 값의 범위는 \n이다.---③\n------------------------------------------------------[3점]  \n이라 하면, 주어진 방정식의 해는 \n함수 의 그래프와 직선 의 교점의 좌표이다.\n다항식 를 정리하면 이고 가 방정식 의 한 근이므로,\n (은 자연수, ≤)를 만족한다.\n과 ③에 의해 \n이다.\n------------------------------------------------------[4점]  \n그러므로 실수 의 범위는 \n\n\n (또는 \n\n).\n------------------------------------------------------[2점]  \n[풀이2] \n조건에 의해 --①\n이므로 이다.\n≤이므로 이다.\n그러므로 을 만족하는 자연수 이다.\n------------------------------------------------------[3점]  \n을 ②에 대입하면, \n를 만족한다.--②\n따라서 ②와 ≤을 동시에 만족하는 의 값의 범위는 \n이다.--③\n------------------------------------------------------[3점]  \n는 에 대한 방정식 의 한 근이고 \n를 만족한다.\n이라 하면, 주어진 방정식의 해는 \n함수 의 그래프와 직선 의 교점의 좌표이다.\n는 모든 실수에서 연속이고, \n\n\n≠이므로,\n사잇값의 정리에 의해 \n과  사이에 인 가 \n열린구간 \n에서 적어도 하나 존재한다.\n즉, \n× \n", "criterion_id": null, "id": "37451834-725d-5364-bbab-1e4868f570c8", "position": 2, "solution_id": "88f3ee28-4d73-55e3-985c-f741e440f1e5"}'::jsonb)) passed
