select 'guard-82' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='02508d76-dbb9-55e6-817a-765bc9e0dad3' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 15 -\n------------------------------------------------------[4점]  \n그러므로 실수 의 값의 범위는 \n\n\n(또는 \n\n)이다.\n------------------------------------------------------[2점]  \n[답안 2-3] (13점)\nsin는 주기가 \n\n인 주기함수이다.\n------------------------------------------------------[2점]  \n따라서 sin와 \n\n의 교점의 좌표가 이상이고 이하인 교점의 개수는 \n좌표가 이상이고 이하인 교점의 개수와 같다.\n이때 sin와 \n\n이 만나는 점의 개수인 를 구하면,\nⅰ) 일 때,  \nⅱ) ⋯일 때, \nⅲ) 일 때, \nⅳ) ≤≤일 때, 0\n------------------------------------------------------[8점]\n*ⅰ)~ⅳ) 각 풀이당 2점  \n그러므로 \n\n\n\n\n\n× \n------------------------------------------------------[3점]  \n[답안 2-4] (15점)\n는  또는 ≥일 때 ,\n≤일 때 이다.\n이므로 \n\n\n\n\n\n\n\n\n\n\n------------------------------------------------------[6점]  \n     =\n이다.\n\n이므로 ′인 ± 이다.\n이 중에 인 이므로,\n------------------------------------------------------[4점]  \n증가와 감소를 표로 나타내면 다음과 같다.\n\n\n⋯\n\n⋯\n′\n\n\n\n\n↘\n극소\n↗\n------------------------------------------------------[3점]  \n", "criterion_id": null, "id": "02508d76-dbb9-55e6-817a-765bc9e0dad3", "position": 3, "solution_id": "88f3ee28-4d73-55e3-985c-f741e440f1e5"}'::jsonb)) passed
