select 'guard-83' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='ab017637-cb03-5f38-bd89-849a88ef1c91' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 16 -\n 는 일 때 극솟값 \n을 갖고, 극댓값은 갖지 않는다.\n------------------------------------------------------[2점]  \n \n", "criterion_id": null, "id": "ab017637-cb03-5f38-bd89-849a88ef1c91", "position": 4, "solution_id": "88f3ee28-4d73-55e3-985c-f741e440f1e5"}'::jsonb)) passed
