select 'guard-89' check_name,(exists(select 1 from public.math_scoring_criteria where id='d13a4b05-ede0-54ae-aca1-2f98208011af' and to_jsonb(math_scoring_criteria) @> '{"criterion_key": "q2-official-page-13", "description": "- 13 -\n하위문항\n채점기준\n배점\n2-1\n원의 중심, 즉 한 점에서 원에 접하는 직선까지의 거리를 활용하여 원의 중심과 반지름을 \n구할 수 있다. \nŸ\n중심에서 두 직선까지의 거리를 활용하여 값을 구하면 (4점)\nŸ\n구한 값을 활용하여 반지름을 구하고, 순서쌍으로 표현하면 (6점)\n10\n2-2\n주어진 조건을 미지수가 1개인 연립부등식으로 나타내고, 인수분해를 활용하여(또는 \n연속함수의 성질) 값의 범위를 구할 수 있다.\nŸ\n조건을 이용하여 미지수가 1개인 연립부등식을 활용하여 의 값을 구하면 (3점)\nŸ\n연립부등식을 활용하여 의 범위를 구하면 (3점)\nŸ\n인수분해를 활용하여 실수 의 값의 범위를 구하면 (6점)[풀이1]\n12\nŸ\n연속함수의 성질 및 이차부등식을 활용하여 실수 의 값의 범위를 구하면 (6점)[풀이2]\n2-3\n주어진 사인함수의 그래프와 직선의 그래프가 만나는 교점의 개수를 사인함수의 정의를 \n활용하여 구할 수 있다.\nŸ\n사인함수의 주기를 구하면 (2점)\nŸ\n의 범위에 따라 을 각각 구하면 (8점)\nŸ 의 값을 구하면 (3점)\n13\n2-4\n주어진 두 함수를 활용하여 함수 의 범위를 나누고, 정적분에 미분을 활용하여 극값을 \n구할 수 있다.\nŸ\n주어진 두 함수를 활용하여 함수 의 범위를 나누면 (6점)\nŸ\n함수 가 극값을 가질 를 구하면 (4점)\nŸ\n함수의 증가와 감소를 활용하여 함수 의 극값을 구하면 (5점)\n15\n 7. 예시 답안 혹은 정답\n[답안 2-1] (10점)\n중심 에서 두 직선까지의 거리가 같으므로\n\n\n\n\n. 즉, 이다.\nⅰ) 일 때,\n±  \nⅱ) 일 때,\n.\n------------------------------------------------------[4점]  \n이므로, 와 의 값을 모두 구하면\n일 때 ±\n\n,  일 때 ±\n\n, 일 때, ± 이다. \n따라서 순서쌍 는 \n\n\n\n\n\n\n\n\n 이다.\n------------------------------------------------------[6점]  \n[답안 2-2] (12점)\n", "id": "d13a4b05-ede0-54ae-aca1-2f98208011af", "leaf_id": "2b478cd7-6c71-5a29-b4f4-1ec3aecec712", "official_points": null, "rubric_dimensions": ["logical_development", "computation_accuracy", "final_conclusion"], "source_id": "304d719a-2948-5ed3-88ec-15ff7d582e5c"}'::jsonb)) passed
