select 'guard-96' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='e60749ed-2909-5f75-b2ca-2a0bb115dbc2' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 5 -\n 7. 예시 답안 혹은 정답\n[답안 1-1](8점)\n이차함수 \n의 \n그래프가 \n축과 \n만나므로 \n이차방정식 \n의 판별식을 이라고 하면\n≥\n즉, ≤\n\n\n  ---------------------------------➀\n------------------------------------------------------------------------------------[2점]\n이차함수 의 그래프는 축과 만나지 않으므로 이차방정식 \n의 판별식을 라고 하면\n\n즉, \n\n\n -------------------------------------➁\n------------------------------------------------------------------------------------[2점]\n➀, ➁에서 \n\n\n≤\n\n\n------------------------------------------------------------------------------------[2점]\n\n\n\n\n\n≤\n\n\n에서\nlim\n→∞\n\n\n\n\n이고, lim\n→∞\n\n\n\n\n이므로 수열의 극한의 대소관계에 의하여\nlim\n→∞\n\n\n\n\n\n------------------------------------------------------------------------------------[2점]\n------------------------------------------------------------------------------------[총 8점]\n[답안 1-2](10점)\n(1) ′ 이므로\n점 에서의 접선의 방정식은\n\n------------------------------------------------------------------------------------[3점]\n(2) ′이므로 ′에서 \n′의 부호를 조사하여 의 증가와 감소를 표로 나타내면 다음과 같다. \n", "criterion_id": null, "id": "e60749ed-2909-5f75-b2ca-2a0bb115dbc2", "position": 1, "solution_id": "9e3597f8-1ec8-52e8-8850-0d873122221f"}'::jsonb)) passed
