select 'guard-97' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='d8c88b4e-18d1-5ee2-a599-42cb9a349c65' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 6 -\n따라서, 는 에서 극소이고 극솟값은 이다.\n------------------------------------------------------------------------------------[3점]\n(3) 이 접선이 점 을 지나므로\n\n방정식을 정리하면  ---------------------➀\n------------------------------------------------------------------------------------[2점]\n이차방정식 ➀이 서로 다른 두 개의 실근을 가질 때 서로 다른 두 개의 접선을 그을 수 있으므로 \n➀의 판별식을 라 하면\n 에서  또는 \n------------------------------------------------------------------------------------[2점]\n------------------------------------------------------------------------------------[총 10점]\n[답안 1-3](14점)\nlim\n→∞\n\n\n\n\n\n\nlim\n→∞\n\n\n\n\n\n\n\n\n\n\n------------------------------------------------------------------------------------[4점]\n제시문 다)에서, \n\n라 하면 \n, , 이므로\nlim\n→∞\n\n\n\n\n\n\n\n\n\nlim\n→∞\n\n\n\n\n∆\n\n\n\n\n\n\n\nln \n------------------------------------------------------------------------------------[5점]\nln 라 하면 \n\n\n이고,\n일 때, ln , 일 때, ln 이다. \n따라서, lim\n→∞\n\n\n\n\n\n\n\nln\nln\n\n\n\n\n\n\nln\nln\n\n\nln ln \n[참고] 위의 해는 다음과 같은 결과 등 다양한 형태로도 나타날 수 있다.\n\n\nln ln \n\n\nln ln ln ln \n\n\nln ln ln ln \n\nln ln ln ln \n------------------------------------------------------------------------------------[5점]\n\n⋯\n\n⋯\n′\n\n\n\n\n↘\n\n↗\n", "criterion_id": null, "id": "d8c88b4e-18d1-5ee2-a599-42cb9a349c65", "position": 2, "solution_id": "9e3597f8-1ec8-52e8-8850-0d873122221f"}'::jsonb)) passed
