select 'guard-98' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='322ac503-0d6b-5800-8a0e-1cd26969d047' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 7 -\n------------------------------------------------------------------------------------[총 14점]\n[다른 풀이]\nlim\n→∞\n\n\n\n\n\n\nlim\n→∞\n\n\n\n\n\n\n\n\n\n\n------------------------------------------------------------------------------------[4점]\n제시문 다)에서, \n라 하면 \n, , 이므로\nlim\n→∞\n\n\n\n\n\n\n\n\n\nlim\n→∞\n\n\n\n\n\n\n\n\n\nln \n라 하면 이고,\n일 때, , 일 때, 이다.\n따라서, \n\n\n\n\nln \n\n\n\nln \n------------------------------------------------------------------------------------[5점]\nln 라 하면 \n이고,\n일 때, ln , 일 때, ln 이다. \n따라서, lim\n→∞\n\n\n\n\n\n\n\nln\nln\n\n\n\n\n\n\nln\nln\n\n\nln ln \n[참고] 위의 해는 다음과 같은 결과로도 나타낼수 있다.\n\n\nln ln \n\n\nln ln ln ln \n\n\nln ln ln ln \n\nln ln ln ln \n------------------------------------------------------------------------------------[5점]\n------------------------------------------------------------------------------------[총 14점]\n[답안 1-4](18점)\n(1) 교점의 개수: 1\n------------------------------------------------------------------------------------[5점]\n(2) 곡선 ln가 곡선 과 오직 한점 A에서 만나고 곡선 \n 위의 점 A에서의 접선과 곡선  위의 점 A에서의 접선이 일치하므로 점 A의 \n좌표를 라 하면\n", "criterion_id": null, "id": "322ac503-0d6b-5800-8a0e-1cd26969d047", "position": 3, "solution_id": "9e3597f8-1ec8-52e8-8850-0d873122221f"}'::jsonb)) passed
