select 'guard-99' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='85bc42e8-9ae5-54d1-9dfb-ae5d6cfd7ede' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 8 -\nln---------------------------- (ㄱ)\n\n\n --------------------------------- (ㄴ)\n------------------------------------------------------------------------------------[3점]\n(ㄱ), (ㄴ)에서 ln\n\n이고 이므로\nln\n\n\n------------------------------------------------------------------------------------[3점]\nln\n\n의 해를 라 하면 를 만족한다.\n-----------------------------------------(ㄷ)\n(ㄷ)을 (ㄴ)에 대입하면\n\n\n, \n\n\nln\n\n\n따라서, ln\n\n\n------------------------------------------------------------------------------------[4점]\nln\n\n\n′\n\n\n\n\n\n\n\n\n\n′\n\n\n\n\n\n\n------------------------------------------------------------------------------------[3점]\n------------------------------------------------------------------------------------[총 18점]\n[다른 풀이]\n(2) 곡선 ln가 곡선 과 오직 한점 A에서 만나고 곡선 \n 위의 점 A에서의 접선과 곡선  위의 점 A에서의 접선이 일치하므로 점 A의 \n좌표를 라 하면\nln ----------------------------(ㄱ)\n\n\n --------------------------------- (ㄴ)\n------------------------------------------------------------------------------------[3점]\n", "criterion_id": null, "id": "85bc42e8-9ae5-54d1-9dfb-ae5d6cfd7ede", "position": 4, "solution_id": "9e3597f8-1ec8-52e8-8850-0d873122221f"}'::jsonb)) passed
