select 'guard-100' check_name,(exists(select 1 from public.math_canonical_solution_steps where id='49022ce6-c931-5c4e-8832-deeac9b9c795' and to_jsonb(math_canonical_solution_steps) @> '{"body": "- 9 -\nln\n\n\nln\n\n------------------------------- (ㄷ)\n------------------------------------------------------------------------------------[3점]\nln\n\n의 해를 라 하면 를 만족한다.\n-----------------------------------------(ㄹ)\n(ㄹ)을 (ㄷ)에 대입하면\n따라서, ln\n\n\n------------------------------------------------------------------------------------[4점]\nln\n\n\n′\n\n\n\n\n\n\n\n\n\n′\n\n\n\n\n\n\n------------------------------------------------------------------------------------[3점]\n------------------------------------------------------------------------------------[총 18점]\n", "criterion_id": null, "id": "49022ce6-c931-5c4e-8832-deeac9b9c795", "position": 5, "solution_id": "9e3597f8-1ec8-52e8-8850-0d873122221f"}'::jsonb)) passed
