select 'guard-101' check_name,(exists(select 1 from public.math_canonical_solutions where id='9e3597f8-1ec8-52e8-8850-0d873122221f' and to_jsonb(math_canonical_solutions) @> '{"body": "- 5 -\n 7. 예시 답안 혹은 정답\n[답안 1-1](8점)\n이차함수 \n의 \n그래프가 \n축과 \n만나므로 \n이차방정식 \n의 판별식을 이라고 하면\n≥\n즉, ≤\n\n\n  ---------------------------------➀\n------------------------------------------------------------------------------------[2점]\n이차함수 의 그래프는 축과 만나지 않으므로 이차방정식 \n의 판별식을 라고 하면\n\n즉, \n\n\n -------------------------------------➁\n------------------------------------------------------------------------------------[2점]\n➀, ➁에서 \n\n\n≤\n\n\n------------------------------------------------------------------------------------[2점]\n\n\n\n\n\n≤\n\n\n에서\nlim\n→∞\n\n\n\n\n이고, lim\n→∞\n\n\n\n\n이므로 수열의 극한의 대소관계에 의하여\nlim\n→∞\n\n\n\n\n\n------------------------------------------------------------------------------------[2점]\n------------------------------------------------------------------------------------[총 8점]\n[답안 1-2](10점)\n(1) ′ 이므로\n점 에서의 접선의 방정식은\n\n------------------------------------------------------------------------------------[3점]\n(2) ′이므로 ′에서 \n′의 부호를 조사하여 의 증가와 감소를 표로 나타내면 다음과 같다. \n\n\n- 6 -\n따라서, 는 에서 극소이고 극솟값은 이다.\n------------------------------------------------------------------------------------[3점]\n(3) 이 접선이 점 을 지나므로\n\n방정식을 정리하면  ---------------------➀\n------------------------------------------------------------------------------------[2점]\n이차방정식 ➀이 서로 다른 두 개의 실근을 가질 때 서로 다른 두 개의 접선을 그을 수 있으므로 \n➀의 판별식을 라 하면\n 에서  또는 \n------------------------------------------------------------------------------------[2점]\n------------------------------------------------------------------------------------[총 10점]\n[답안 1-3](14점)\nlim\n→∞\n\n\n\n\n\n\nlim\n→∞\n\n\n\n\n\n\n\n\n\n\n------------------------------------------------------------------------------------[4점]\n제시문 다)에서, \n\n라 하면 \n, , 이므로\nlim\n→∞\n\n\n\n\n\n\n\n\n\nlim\n→∞\n\n\n\n\n∆\n\n\n\n\n\n\n\nln \n------------------------------------------------------------------------------------[5점]\nln 라 하면 \n\n\n이고,\n일 때, ln , 일 때, ln 이다. \n따라서, lim\n→∞\n\n\n\n\n\n\n\nln\nln\n\n\n\n\n\n\nln\nln\n\n\nln ln \n[참고] 위의 해는 다음과 같은 결과 등 다양한 형태로도 나타날 수 있다.\n\n\nln ln \n\n\nln ln ln ln \n\n\nln ln ln ln \n\nln ln ln ln \n------------------------------------------------------------------------------------[5점]\n\n⋯\n\n⋯\n′\n\n\n\n\n↘\n\n↗\n\n\n- 7 -\n------------------------------------------------------------------------------------[총 14점]\n[다른 풀이]\nlim\n→∞\n\n\n\n\n\n\nlim\n→∞\n\n\n\n\n\n\n\n\n\n\n------------------------------------------------------------------------------------[4점]\n제시문 다)에서, \n라 하면 \n, , 이므로\nlim\n→∞\n\n\n\n\n\n\n\n\n\nlim\n→∞\n\n\n\n\n\n\n\n\n\nln \n라 하면 이고,\n일 때, , 일 때, 이다.\n따라서, \n\n\n\n\nln \n\n\n\nln \n------------------------------------------------------------------------------------[5점]\nln 라 하면 \n이고,\n일 때, ln , 일 때, ln 이다. \n따라서, lim\n→∞\n\n\n\n\n\n\n\nln\nln\n\n\n\n\n\n\nln\nln\n\n\nln ln \n[참고] 위의 해는 다음과 같은 결과로도 나타낼수 있다.\n\n\nln ln \n\n\nln ln ln ln \n\n\nln ln ln ln \n\nln ln ln ln \n------------------------------------------------------------------------------------[5점]\n------------------------------------------------------------------------------------[총 14점]\n[답안 1-4](18점)\n(1) 교점의 개수: 1\n------------------------------------------------------------------------------------[5점]\n(2) 곡선 ln가 곡선 과 오직 한점 A에서 만나고 곡선 \n 위의 점 A에서의 접선과 곡선  위의 점 A에서의 접선이 일치하므로 점 A의 \n좌표를 라 하면\n\n\n- 8 -\nln---------------------------- (ㄱ)\n\n\n --------------------------------- (ㄴ)\n------------------------------------------------------------------------------------[3점]\n(ㄱ), (ㄴ)에서 ln\n\n이고 이므로\nln\n\n\n------------------------------------------------------------------------------------[3점]\nln\n\n의 해를 라 하면 를 만족한다.\n-----------------------------------------(ㄷ)\n(ㄷ)을 (ㄴ)에 대입하면\n\n\n, \n\n\nln\n\n\n따라서, ln\n\n\n------------------------------------------------------------------------------------[4점]\nln\n\n\n′\n\n\n\n\n\n\n\n\n\n′\n\n\n\n\n\n\n------------------------------------------------------------------------------------[3점]\n------------------------------------------------------------------------------------[총 18점]\n[다른 풀이]\n(2) 곡선 ln가 곡선 과 오직 한점 A에서 만나고 곡선 \n 위의 점 A에서의 접선과 곡선  위의 점 A에서의 접선이 일치하므로 점 A의 \n좌표를 라 하면\nln ----------------------------(ㄱ)\n\n\n --------------------------------- (ㄴ)\n------------------------------------------------------------------------------------[3점]\n\n\n- 9 -\nln\n\n